create or replace function public.search_community(search_text text,page_cursor jsonb default '{}')returns jsonb language sql stable security invoker set search_path=''as $$with
matching_posts as(select *from public.posts where length(search_text)between 2 and 200 and not(page_cursor ? 'posts' and page_cursor->>'posts' is null) and(id>coalesce((page_cursor->>'posts')::uuid,'00000000-0000-0000-0000-000000000000'::uuid))and search_vector@@websearch_to_tsquery('english',search_text)order by id limit 30),
matching_profiles as(select *from public.profiles where length(search_text)between 2 and 200 and not(page_cursor ? 'profiles' and page_cursor->>'profiles' is null) and(id>coalesce((page_cursor->>'profiles')::uuid,'00000000-0000-0000-0000-000000000000'::uuid))and to_tsvector('english',name||' '||methods||' '||equipment||' '||array_to_string(interests,' '))@@websearch_to_tsquery('english',search_text)order by id limit 30),
matching_papers as(select *from public.papers where length(search_text)between 2 and 200 and not(page_cursor ? 'papers'and page_cursor->>'papers'is null)and id>coalesce(page_cursor->>'papers','')and to_tsvector('english',title||' '||venue||' '||doi||' '||pmid||' '||array_to_string(authors,' '))@@websearch_to_tsquery('english',search_text)order by id limit 30),matching_projects as(select *from public.projects where length(search_text)between 2 and 200 and not(page_cursor ? 'projects' and page_cursor->>'projects' is null) and(id>coalesce((page_cursor->>'projects')::uuid,'00000000-0000-0000-0000-000000000000'::uuid))and to_tsvector('english',title||' '||problem||' '||methods||' '||needs||' '||equipment)@@websearch_to_tsquery('english',search_text)order by id limit 30)
select jsonb_build_object('papers',(select coalesce(jsonb_agg(x order by id),'[]')from matching_papers x),'posts',(select coalesce(jsonb_agg(x order by id),'[]')from matching_posts x),'profiles',(select coalesce(jsonb_agg(x order by id),'[]')from matching_profiles x),'projects',(select coalesce(jsonb_agg(x order by id),'[]')from matching_projects x),'cursor',jsonb_build_object('papers',(select case when count(*)=30 then max(id)else null end from matching_papers),'posts',(select case when count(*)=30 then max(id::text)else null end from matching_posts),'profiles',(select case when count(*)=30 then max(id::text)else null end from matching_profiles),'projects',(select case when count(*)=30 then max(id::text)else null end from matching_projects)))$$;
revoke all on function public.search_community(text,jsonb)from public;grant execute on function public.search_community(text,jsonb)to anon,authenticated;


alter table public.preferences add column categories text[] not null default array['reply','accepted','collaboration','membership','mention','topic','moderation']check(categories<@array['reply','accepted','collaboration','membership','mention','topic','moderation']::text[]);
create or replace function private.notify(target uuid,event text,cat text,msg text,destination text)returns void language sql security definer set search_path=''as $$insert into public.notifications(user_id,event_key,category,text,path)select target,event,cat,left(msg,500),destination where target<>auth.uid()and coalesce((select in_app and cat=any(categories)from public.preferences where user_id=target),true)and(cat in('membership','moderation')or(select count(*)from public.notifications where user_id=target and created_at>now()-interval '1 day')<50)on conflict(user_id,event_key)do nothing$$;
create function public.notification_preferences(selected_categories text[])returns void language plpgsql security definer set search_path=''as $$begin if auth.uid()is null or cardinality(selected_categories)>7 then raise insufficient_privilege;end if;perform private.rate_limit('all',60);insert into public.preferences(user_id,categories)values(auth.uid(),selected_categories)on conflict(user_id)do update set categories=excluded.categories;end$$;
revoke all on function public.notification_preferences(text[])from public,anon;grant execute on function public.notification_preferences(text[])to authenticated;
create function private.discussion_notifications()returns trigger language plpgsql security definer set search_path=''as $$declare pid uuid;owner uuid;txt text;project uuid;vis text;state text;target uuid;event text;begin
 if tg_table_name='posts'then pid:=new.id;txt:=new.body;else pid:=new.post_id;txt:=new.body;end if;
 select author_id,project_id,visibility,public.posts.state into owner,project,vis,state from public.posts where id=pid;
 if vis='private'or state<>'published'then return new;end if;event:='mention:'||new.id;
 for target in select p.id from public.profiles p where p.handle in(select (regexp_matches(txt,'@([a-z0-9_]{3,32})','g'))[1])and p.membership='approved'and not p.suspended and not exists(select 1 from public.blocks where(user_id=p.id and target_id=new.author_id)or(target_id=p.id and user_id=new.author_id))and(project is null or exists(select 1 from public.projects pr where pr.id=project and(pr.visibility='public'or exists(select 1 from public.project_members m where m.project_id=project and m.user_id=p.id))))limit 20 loop perform private.notify(target,event,'mention','You were mentioned in a discussion','/post/'||pid::text);end loop;
 if tg_table_name='posts'then
 for target in select p.id from public.profiles p join public.preferences f on f.user_id=p.id where p.membership='approved'and not p.suspended and f.interests&&new.tags and not f.muted&&new.tags and not exists(select 1 from public.blocks where(user_id=p.id and target_id=new.author_id)or(target_id=p.id and user_id=new.author_id))and(project is null or exists(select 1 from public.projects pr where pr.id=project and(pr.visibility='public'or exists(select 1 from public.project_members m where m.project_id=project and m.user_id=p.id))))limit 100 loop perform private.notify(target,'topic:'||pid::text,'topic','New contribution in a followed research interest','/post/'||pid::text);end loop;end if;return new;end$$;
revoke all on function private.discussion_notifications()from public;
create trigger post_notifications after insert on public.posts for each row execute function private.discussion_notifications();
create trigger comment_mentions after insert on public.comments for each row execute function private.discussion_notifications();
create function private.moderation_notification()returns trigger language plpgsql security definer set search_path=''as $$begin if old.state<>new.state then perform private.notify(new.author_id,'moderation:'||new.id::text||':'||new.updated_at::text,'moderation','A contribution status changed: '||new.state,'/notifications');end if;return new;end$$;
revoke all on function private.moderation_notification()from public;
create trigger post_moderation_notification after update of state on public.posts for each row execute function private.moderation_notification();
create or replace function public.trust_metadata()returns jsonb language sql stable security invoker set search_path=''as $$select jsonb_build_object('taxonomy',(select coalesce(jsonb_agg(name order by name),'[]')from public.topics),'point_rules',(select coalesce(jsonb_agg(x),'[]')from public.contribution_rules x),'subscriptions',(select coalesce(jsonb_agg(x),'[]')from(select *from public.subscriptions limit 100)x),'paper_saves',(select coalesce(jsonb_agg(x),'[]')from(select *from public.paper_saves limit 100)x),'contribution_total',(select coalesce(sum(points),0)from public.contributions where valid and user_id=auth.uid()))$$;
